Lemma aplace_stack : forall O n, aceil <= O -> O + n + 8 <= AAPP_HI -> aplace O n.
Proof.
  intros O n H1 H2. pose proof aceil_facts as (AF & _). unfold aplace, AIMG_TOP, AHI_LO in *. lia.
Qed.

Lemma aplace_sub : forall O n a k, aplace O n -> O <= a -> a + k <= O + n -> 0 <= k -> aplace a k.
Proof. intros O n a k (P1 & P2 & P3 & P4) H1 H2 Hk. unfold aplace. lia. Qed.

Lemma aplace_bounds : forall O n, aplace O n -> 0 < O /\ AIMG_TOP <= O /\ O + n + 8 <= AAPP_HI.
Proof. intros O n (P1 & P2 & P3 & P4). auto. Qed.

Lemma aplace_noshadow : forall O n, aplace O n -> O + n <= ALOWSH_LO \/ AHI_LO <= O.
Proof. intros O n (P1 & P2 & P3 & P4). exact P4. Qed.
