Lemma in_app_mem_aplace : forall O n lo hi, aplace O n -> O <= lo -> hi <= O + n -> in_app_mem lo hi.
Proof.
  intros O n lo hi (P1 & P2 & P3 & [P4|P4]) L1 L2; unfold in_app_mem, ALOWSH_LO, AHI_LO, AIMG_TOP in *; rewrite ?ASHADOW_BASE_val in *.
  - left. pose proof ASHADOW_BASE_val. lia.
  - right. lia.
Qed.


